@import "@fontsource-variable/instrument-sans";
@import "@fontsource/ibm-plex-mono/400.css";
@import "@fontsource/ibm-plex-mono/500.css";

/* Light (faithful): page warm white #fdfcf4, text meteorite black #2a2c2f, bands warm grey #ece8e3
   and moon rock #b3aba3, quiet text asteroid dust #897f75, accent solar orange #ff5623.
   chart-1…5 = orange, green #2da046, asteroid dust, moon rock, black. Dark is the same system on a
   near-black page. */
:root {
  --background: #fdfcf4;
  --foreground: #2a2c2f;
  --card: #ece8e3;
  --card-foreground: #2a2c2f;
  --popover: #ffffff;
  --popover-foreground: #2a2c2f;
  --primary: #2a2c2f;
  --primary-foreground: #fdfcf4;
  --secondary: #ece8e3;
  --secondary-foreground: #2a2c2f;
  --muted: #b3aba3;
  --muted-foreground: #897f75;
  --accent: #ece8e3;
  --accent-foreground: #2a2c2f;
  --destructive: oklch(0.577 0.245 27.325);
  --destructive-foreground: #ffffff;
  --border: #b3aba366;
  --input: #2a2c2f33;
  --ring: #2a2c2f80;
  --highlight: #ff5623;
  --highlight-foreground: #ffffff;
  --glow: #ff5623;
  --chart-1: #ff5623;
  --chart-2: #2da046;
  --chart-3: #897f75;
  --chart-4: #b3aba3;
  --chart-5: #000000;
  --sidebar: #ffffff;
  --sidebar-foreground: #2a2c2f;
  --sidebar-primary: #2a2c2f;
  --sidebar-primary-foreground: #fdfcf4;
  --sidebar-accent: #ece8e3;
  --sidebar-accent-foreground: #2a2c2f;
  --sidebar-border: #b3aba366;
  --sidebar-ring: #2a2c2f80;

  --typeface-body: "Instrument Sans Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-display: var(--typeface-body);
  --typeface-mono: "IBM Plex Mono", ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --radius: 0.125rem;
  --page-width: 90rem;
  --page-gutter: clamp(1rem, calc(4.5vw - 0.7rem), 2.5rem);
  --section-y: 7.5rem;
}

.dark {
  --background: #1c1d1f;
  --foreground: #fdfcf4;
  --card: #2a2c2f;
  --card-foreground: #fdfcf4;
  --popover: #2f3134;
  --popover-foreground: #fdfcf4;
  --primary: #fdfcf4;
  --primary-foreground: #2a2c2f;
  --secondary: #2a2c2f;
  --secondary-foreground: #fdfcf4;
  --muted: #5b5650;
  --muted-foreground: #b3aba3;
  --accent: #3a3c3f;
  --accent-foreground: #fdfcf4;
  --destructive: oklch(0.704 0.191 22.216);
  --destructive-foreground: #ffffff;
  --border: #fdfcf433;
  --input: #fdfcf426;
  --ring: #fdfcf480;
  --highlight: #ff5623;
  --highlight-foreground: #ffffff;
  --glow: #ff5623;
  --chart-1: #ff5623;
  --chart-2: #2da046;
  --chart-3: #897f75;
  --chart-4: #b3aba3;
  --chart-5: #000000;
  --sidebar: #2f3134;
  --sidebar-foreground: #fdfcf4;
  --sidebar-primary: #fdfcf4;
  --sidebar-primary-foreground: #2a2c2f;
  --sidebar-accent: #3a3c3f;
  --sidebar-accent-foreground: #fdfcf4;
  --sidebar-border: #fdfcf433;
  --sidebar-ring: #fdfcf480;
}
